import { Hono } from "hono";
import type { Context } from "hono";
import { csrf } from "hono/csrf";
import type { ContentfulStatusCode } from "hono/utils/http-status";
import { renderHtml } from "./ui";
import { cfApiFetch } from "./api/cloudflare";
import { isValidAccessRequest, timingSafeEqual } from "./auth";

// `Env` is the ambient global interface generated by `wrangler types` (see
// worker-configuration.d.ts, gitignored — run `npm run types` after setting up
// wrangler.toml). Do not hand-write binding types here; they drift from config.

const app = new Hono<{ Bindings: Env }>();

// Defense in depth: our handlers only ever accept application/json bodies, so
// classic form/multipart CSRF can't reach them anyway (no CORS preflight
// approval for cross-site JSON fetches, and a form-urlencoded/multipart body
// wouldn't parse as JSON). This guards the content-types it's actually meant
// for in case a form-style endpoint ever gets added later.
app.use("*", csrf());

type AppContext = Context<{ Bindings: Env }>;

/**
 * Gates the admin/config endpoints (gateway settings, custom-cost writes,
 * stats). These were previously reachable with zero auth on the public
 * `*.workers.dev` URL — see AGENTS.md Known Limitations for the full writeup.
 * Passes if the caller holds the server's own CLOUDFLARE_API_TOKEN (scripts,
 * CI, the bootstrap flow) OR a verified Cloudflare Access JWT (human login or
 * a configured service token through the Access app that protects the
 * custom domain). Chat (`/api/chat`) and reading your own saved custom costs
 * (`GET /api/costs`) stay intentionally open — that's the documented
 * "service identity, no Access" demo mode.
 */
async function requireAdmin(c: AppContext): Promise<Response | null> {
  const env = c.env;
  const auth = c.req.header("Authorization");
  if (auth && (await timingSafeEqual(auth, `Bearer ${env.CLOUDFLARE_API_TOKEN}`))) {
    return null;
  }
  const jwt = c.req.header("Cf-Access-Jwt-Assertion");
  if (await isValidAccessRequest(jwt, env.CF_ACCESS_TEAM_DOMAIN, env.CF_ACCESS_AUD)) {
    return null;
  }
  return c.json({ ok: false, error: "Unauthorized" }, 401);
}

// ─── HTML Client ─────────────────────────────────────────────────────────────

app.get("/", (c) => serveHtml(c));
app.get("/demo", (c) => serveHtml(c));
app.get("/demo/", (c) => serveHtml(c));

app.get("/demo/logout", (c) => {
  const logoutUrl = `https://${c.env.GATEWAY_NAME}/cdn-cgi/access/logout`;
  return c.redirect(logoutUrl);
});

function serveHtml(c: AppContext) {
  const isGateway = c.req.path.startsWith("/demo");
  const accessLogoutUrl = `https://${c.env.GATEWAY_NAME}/cdn-cgi/access/logout`;
  return c.html(
    renderHtml({
      gatewayName: c.env.GATEWAY_NAME,
      isGateway,
      accessLogoutUrl,
    }),
  );
}

// ─── API Routes (mounted under both /api and /demo/api) ────────────────────────

type ApiHandler = (c: AppContext) => Promise<Response> | Response;

function dualRoute(method: "get" | "post", path: string, handler: ApiHandler) {
  const register = method === "get" ? app.get.bind(app) : app.post.bind(app);
  register(`/api${path}`, handler);
  register(`/demo/api${path}`, handler);
}

const isValidCost = (v: unknown): v is number =>
  typeof v === "number" && Number.isFinite(v) && v >= 0;

const safeKvParse = <T>(raw: string | null): T | null => {
  if (!raw) return null;
  try {
    return JSON.parse(raw) as T;
  } catch {
    return null;
  }
};

// Shape of the AI Gateway /compat/chat/completions response we actually read.
// Parsed from an external API, so fields are optional — never guaranteed by a contract.
type ChatCompletionResponse = {
  model?: string;
  usage?: { prompt_tokens?: number; completion_tokens?: number };
  choices?: unknown[];
  error?: { message?: string };
  errors?: Array<{ message?: string }>;
  _raw?: string;
};

const errorMessage = (err: unknown): string => (err instanceof Error ? err.message : String(err));

// Shapes for the Cloudflare REST API (client/v4) responses this Worker reads.
// Loosely typed on purpose — these are external API payloads, not a contract we control.
type CfApiError = { message?: string };
type CfApiResult<T = unknown> = { result?: T; errors?: CfApiError[] };
// Hazard-category action map AI Gateway's Guardrails (Llama Guard) uses —
// categories S1-S13 plus P1 (prompt injection), each "FLAG" | "BLOCK".
// Loosely typed since we only ever pass this through unchanged or omit it.
type GuardrailsCategories = Record<string, "FLAG" | "BLOCK">;
type GuardrailsConfig = { prompt?: GuardrailsCategories; response?: GuardrailsCategories };

// Only the fields this Worker specifically reads or reasons about are
// declared here. At runtime the gateway resource has 20+ other fields
// (log_management, zdr, workers_ai_billing_mode, id, created_at, ...) that
// settingsHandler preserves too, via spreading the whole parsed object —
// see settingsHandler for why a narrower allowlist approach already bit us.
type GatewayConfig = {
  cache_ttl?: number;
  rate_limiting_limit?: number;
  rate_limiting_interval?: number;
  rate_limiting_technique?: string;
  collect_logs?: boolean;
  cache_invalidate_on_update?: boolean;
  // "Authenticated Gateway" — requires a cf-aig-authorization header on every
  // request when true. Confirmed live that an earlier version of
  // settingsHandler was silently flipping this to false (it wasn't in the
  // handler's old explicit field list), which broke Access-authenticated
  // gateway-mode chat with a 401. Not touched intentionally by this app —
  // declared here only so the spread-preservation behavior is documented.
  authentication?: boolean;
  guardrails?: GuardrailsConfig;
  dlp?: unknown;
};

// Applied the first time a user enables Guardrails with no prior config to
// restore (e.g. after a previous disable, which clears it server-side per
// Cloudflare's docs). FLAG (not BLOCK) everywhere — visible in logs without
// risking an unexpected block mid-demo. P1 is prompt-injection detection.
const DEFAULT_GUARDRAILS: GuardrailsConfig = {
  prompt: {
    S1: "FLAG",
    S2: "FLAG",
    S3: "FLAG",
    S4: "FLAG",
    S5: "FLAG",
    S6: "FLAG",
    S7: "FLAG",
    S8: "FLAG",
    S9: "FLAG",
    S10: "FLAG",
    S11: "FLAG",
    S12: "FLAG",
    S13: "FLAG",
    P1: "FLAG",
  },
  response: {
    S1: "FLAG",
    S2: "FLAG",
    S3: "FLAG",
    S4: "FLAG",
    S5: "FLAG",
    S6: "FLAG",
    S7: "FLAG",
    S8: "FLAG",
    S9: "FLAG",
    S10: "FLAG",
    S11: "FLAG",
    S12: "FLAG",
    S13: "FLAG",
    P1: "FLAG",
  },
};

const isGuardrailsOn = (guardrails: GuardrailsConfig | undefined): boolean =>
  Boolean(
    guardrails &&
    (Object.keys(guardrails.prompt ?? {}).length > 0 ||
      Object.keys(guardrails.response ?? {}).length > 0),
  );

// Shared by settingsHandler, statsHandler, and guardrailsHandler — all three
// need to read the gateway's current config before writing it back, since
// the PUT endpoint replaces the whole resource (see settingsHandler for why
// that matters).
async function fetchCurrentGatewayConfig(env: Env): Promise<GatewayConfig> {
  const res = await cfApiFetch(
    env,
    `/accounts/${env.CLOUDFLARE_ACCOUNT_ID}/ai-gateway/gateways/${env.GATEWAY_ID}`,
  );
  const data = await res.json<CfApiResult<GatewayConfig>>();
  return res.ok ? (data.result ?? {}) : {};
}

// Base PUT body shared by any handler that writes the gateway's config:
// spread the full current config (preserves everything we're not touching —
// see settingsHandler for the authentication/dlp incident that motivated
// this), plus the three fields the API requires outright on every write.
function baseGatewayPutBody(current: GatewayConfig): Record<string, unknown> {
  return {
    ...current,
    cache_ttl: current.cache_ttl ?? 0,
    collect_logs: current.collect_logs ?? true,
    cache_invalidate_on_update: current.cache_invalidate_on_update ?? false,
  };
}

type SpendLimitRule = { id: string };
type AnalyticsGroup = {
  count?: number;
  sum?: { tokensIn?: number; tokensOut?: number; cost?: number };
};
type GraphQLAnalyticsResponse = {
  data?: { viewer?: { accounts?: Array<{ aiGatewayRequestsAdaptiveGroups?: AnalyticsGroup[] }> } };
};

const MAX_METADATA_STRING_LENGTH = 200;
const MAX_PROMPT_LENGTH = 4000;
const MAX_CACHE_KEY_LENGTH = 512;

// Control characters (incl. CR/LF) are rejected rather than relying solely on
// the Fetch API's own Headers validation. The runtime does reject raw CRLF in
// header values, but surfacing that as a clean 400 here beats an unhandled
// throw turning into a 500 for a client-supplied value.
// eslint-disable-next-line no-control-regex -- matching control chars is the point of this check
const hasControlChars = (s: string): boolean => /[\x00-\x1f\x7f]/.test(s);

const validateMetadata = (metadata: Record<string, unknown>): string | null => {
  const keys = Object.keys(metadata);
  if (keys.length > 5) return "metadata supports at most 5 key-value pairs";
  for (const key of keys) {
    if (key.startsWith("cf.")) return `metadata key "${key}" uses reserved cf. prefix`;
    const value = metadata[key];
    if (typeof value !== "string" && typeof value !== "number" && typeof value !== "boolean") {
      return `metadata value for "${key}" must be a string, number, or boolean`;
    }
    if (typeof value === "string" && value.length > MAX_METADATA_STRING_LENGTH) {
      return `metadata value for "${key}" exceeds ${MAX_METADATA_STRING_LENGTH} characters`;
    }
  }
  return null;
};

// ─── API: Chat ───────────────────────────────────────────────────────────────

const chatHandler = async (c: AppContext) => {
  const env = c.env;
  const body = (await c.req.json()) as {
    model: string;
    prompt: string;
    cache?: { ttl: number; key?: string; skip?: boolean };
    metadata?: Record<string, string | number | boolean>;
  };
  const { model, prompt, cache, metadata } = body;

  if (typeof model !== "string" || model.length === 0) {
    return c.json({ ok: false, error: "model is required" }, 400);
  }
  if (typeof prompt !== "string" || prompt.length === 0 || prompt.length > MAX_PROMPT_LENGTH) {
    return c.json(
      {
        ok: false,
        error: `prompt must be a non-empty string up to ${MAX_PROMPT_LENGTH} characters`,
      },
      400,
    );
  }
  if (cache?.key !== undefined) {
    if (
      typeof cache.key !== "string" ||
      cache.key.length > MAX_CACHE_KEY_LENGTH ||
      hasControlChars(cache.key)
    ) {
      return c.json(
        {
          ok: false,
          error: `cache.key must be a string without control characters, up to ${MAX_CACHE_KEY_LENGTH} characters`,
        },
        400,
      );
    }
  }

  if (metadata) {
    const metaError = validateMetadata(metadata);
    if (metaError) return c.json({ ok: false, error: metaError }, 400);
  }

  // Read custom cost headers (set by client) or fall back to KV
  const hdrIn = c.req.header("x-custom-cost-in");
  const hdrOut = c.req.header("x-custom-cost-out");
  let customCost: { per_token_in: number; per_token_out: number } | undefined;

  if (hdrIn && hdrOut) {
    customCost = { per_token_in: parseFloat(hdrIn), per_token_out: parseFloat(hdrOut) };
  } else {
    const kv = safeKvParse<{ per_token_in: number; per_token_out: number }>(
      await env.SETTINGS.get("custom_costs"),
    );
    if (kv && isValidCost(kv.per_token_in) && isValidCost(kv.per_token_out)) {
      customCost = { per_token_in: kv.per_token_in, per_token_out: kv.per_token_out };
    }
  }

  // Cloudflare REST API for Workers AI through AI Gateway custom domain
  // Service token auth for Identity-Aware Gateway (Cloudflare Access)
  const upstreamUrl = `https://${env.GATEWAY_NAME}/compat/chat/completions`;
  const upstreamHeaders: Record<string, string> = {
    Authorization: `Bearer ${env.CLOUDFLARE_API_TOKEN}`,
    "Content-Type": "application/json",
    "CF-Access-Client-Id": env.CF_ACCESS_CLIENT_ID,
    "CF-Access-Client-Secret": env.CF_ACCESS_CLIENT_SECRET,
  };
  const upstreamBody = {
    model: `workers-ai/${model}`,
    messages: [{ role: "user", content: prompt }],
  };

  // Add custom cost header if configured
  if (customCost) {
    upstreamHeaders["cf-aig-custom-cost"] = JSON.stringify(customCost);
  }

  // Add caching headers
  if (cache) {
    if (cache.skip) {
      upstreamHeaders["cf-aig-skip-cache"] = "true";
    } else {
      upstreamHeaders["cf-aig-cache-ttl"] = String(cache.ttl);
      if (cache.key) upstreamHeaders["cf-aig-cache-key"] = cache.key;
    }
  }

  // Add custom metadata header
  if (metadata && Object.keys(metadata).length > 0) {
    upstreamHeaders["cf-aig-metadata"] = JSON.stringify(metadata);
  }

  try {
    // 30s — LLM inference can be slow (large models, cold starts); 15s kills valid requests
    const requestStartedAtMs = Date.now();
    const res = await fetch(upstreamUrl, {
      method: "POST",
      headers: upstreamHeaders,
      body: JSON.stringify(upstreamBody),
      signal: AbortSignal.timeout(30000),
    });

    const cacheStatus = res.headers.get("cf-aig-cache-status") || undefined;
    const rawText = await res.text();
    let data: ChatCompletionResponse;
    try {
      data = JSON.parse(rawText) as ChatCompletionResponse;
    } catch {
      data = { _raw: rawText };
    }

    // Calculate estimated cost for display
    let estimatedCost: number | undefined;
    if (data.usage && customCost) {
      const inTokens = data.usage.prompt_tokens ?? 0;
      const outTokens = data.usage.completion_tokens ?? 0;
      estimatedCost = inTokens * customCost.per_token_in + outTokens * customCost.per_token_out;
    }

    // Enrich with what actually ran for this request: Llama Guard
    // evaluations are logged as their own sub-requests when Guardrails is
    // on, so we can show real guardrails activity (count + added latency)
    // alongside the model output. Best-effort — never fails the chat.
    const guardrails = res.ok ? await fetchGuardrailsActivity(env, requestStartedAtMs) : undefined;

    return c.json(
      {
        ok: res.ok,
        status: res.status,
        model: data.model,
        usage: data.usage,
        estimatedCost,
        cacheStatus,
        guardrails,
        choices: data.choices,
        error: data.error?.message || data.errors?.[0]?.message,
      },
      res.status as ContentfulStatusCode,
    );
  } catch (err: unknown) {
    return c.json({ ok: false, error: errorMessage(err) }, 500);
  }
};
// ─── API: Guardrails activity ─────────────────────────────────────────────────

// Shape of one entry from the gateway logs API. Loosely typed — external
// API payload, only the fields we read are declared. Verified live
// (2026-10-28): Llama Guard evaluations are logged as separate entries with
// request_type "llama-guard", model @cf/meta/llama-guard-3-8b, their own
// duration/tokens, and a created_at timestamp within the chat request's
// window. The verdict fields (score/guardrails) stay empty for FLAG-mode
// safe requests — populated only when something is flagged/blocked.
type GatewayLogEntry = {
  created_at?: string;
  request_type?: string;
  duration?: number;
  tokens_in?: number;
  tokens_out?: number;
};

type GuardrailsActivity = {
  evaluations: number;
  totalMs: number;
  entries: Array<{ duration: number; tokens_in: number; created_at?: string }>;
};

// Best-effort lookup of the Llama Guard evaluations that ran for one chat
// request. Correlated by time window, not by event id — the chat response
// carries no event-id header (verified live), and the gateway's own event_id
// isn't exposed to the caller, so "llama-guard entries logged since this
// request started" is the best available signal. Two-second back-dating
// covers clock/ingest skew between the edge and the logs API.
export async function fetchGuardrailsActivity(
  env: Env,
  requestStartedAtMs: number,
): Promise<GuardrailsActivity | undefined> {
  const windowStartMs = requestStartedAtMs - 2000;
  try {
    const res = await cfApiFetch(
      env,
      `/accounts/${env.CLOUDFLARE_ACCOUNT_ID}/ai-gateway/gateways/${env.GATEWAY_ID}/logs?limit=20`,
      { signal: AbortSignal.timeout(5000) },
    );
    const data = await res.json<CfApiResult<GatewayLogEntry[]>>();
    if (!res.ok) return undefined;
    const guardEntries = (data.result ?? []).filter((entry) => {
      if (entry.request_type !== "llama-guard" || !entry.created_at) return false;
      const createdAtMs = Date.parse(entry.created_at);
      return !Number.isNaN(createdAtMs) && createdAtMs >= windowStartMs;
    });
    return {
      evaluations: guardEntries.length,
      totalMs: guardEntries.reduce((sum, entry) => sum + (entry.duration ?? 0), 0),
      entries: guardEntries.map((entry) => ({
        duration: entry.duration ?? 0,
        tokens_in: entry.tokens_in ?? 0,
        created_at: entry.created_at,
      })),
    };
  } catch {
    // Never fail the chat response over activity enrichment.
    return undefined;
  }
}

dualRoute("post", "/chat", chatHandler);

// Activity lookup for gateway mode, where the browser calls the gateway's
// /compat/chat/completions directly and chatHandler's response enrichment
// never runs. The UI calls this after each gateway-mode chat with the
// request's start time. Admin-gated: it exposes Llama Guard evaluation
// metadata (durations, token counts) sourced with the account API token.
const guardrailsActivityHandler = async (c: AppContext) => {
  const gate = await requireAdmin(c);
  if (gate) return gate;
  const sinceParam = c.req.query("since");
  const sinceMs = sinceParam ? Number.parseInt(sinceParam, 10) : Date.now() - 15000;
  if (Number.isNaN(sinceMs)) {
    return c.json({ ok: false, error: "since must be an epoch-milliseconds integer" }, 400);
  }
  const guardrails = await fetchGuardrailsActivity(c.env, sinceMs);
  return c.json({
    ok: true,
    guardrails: guardrails ?? { evaluations: 0, totalMs: 0, entries: [] },
  });
};
dualRoute("get", "/guardrails-activity", guardrailsActivityHandler);

// ─── API: Custom Costs ───────────────────────────────────────────────────────

const costsGetHandler = async (c: AppContext) => {
  const kv = safeKvParse<Record<string, number>>(await c.env.SETTINGS.get("custom_costs"));
  return c.json({ ok: true, costs: kv ?? null });
};
dualRoute("get", "/costs", costsGetHandler);

const costsPostHandler = async (c: AppContext) => {
  const gate = await requireAdmin(c);
  if (gate) return gate;
  const body = (await c.req.json()) as { per_token_in: number; per_token_out: number };
  if (!isValidCost(body?.per_token_in) || !isValidCost(body?.per_token_out)) {
    return c.json(
      { ok: false, error: "per_token_in and per_token_out must be non-negative finite numbers" },
      400,
    );
  }
  await c.env.SETTINGS.put(
    "custom_costs",
    JSON.stringify({
      per_token_in: body.per_token_in,
      per_token_out: body.per_token_out,
    }),
  );
  return c.json({ ok: true });
};
dualRoute("post", "/costs", costsPostHandler);

// ─── API: Gateway Settings ────────────────────────────────────────────────────

const settingsHandler = async (c: AppContext) => {
  const gate = await requireAdmin(c);
  if (gate) return gate;
  const env = c.env;
  const body = (await c.req.json()) as {
    rateLimit: { enabled: boolean; limit: number; interval: number; technique: string };
    spendLimit: { enabled: boolean; budget: number; window: string; scope: string };
  };

  // See fetchCurrentGatewayConfig/baseGatewayPutBody for why this handler
  // reads the current config and spreads it before writing: the PUT
  // endpoint replaces the gateway's config wholesale, and an earlier version
  // of this handler that only sent rate-limiting fields had silently
  // flipped `authentication` to false (breaking Access-authenticated
  // gateway-mode chat with a bare 401) before that was caught.
  const current = await fetchCurrentGatewayConfig(env);
  const putBody: Record<string, unknown> = {
    ...baseGatewayPutBody(current),
    rate_limiting_limit: body.rateLimit.enabled ? body.rateLimit.limit : 0,
    rate_limiting_interval: body.rateLimit.enabled ? body.rateLimit.interval : 0,
    ...(body.rateLimit.enabled ? { rate_limiting_technique: body.rateLimit.technique } : {}),
  };

  // 1. Update gateway rate limiting, preserving everything else
  const gwUpdateRes = await cfApiFetch(
    env,
    `/accounts/${env.CLOUDFLARE_ACCOUNT_ID}/ai-gateway/gateways/${env.GATEWAY_ID}`,
    {
      method: "PUT",
      body: JSON.stringify(putBody),
    },
  );

  if (!gwUpdateRes.ok) {
    const errData = await gwUpdateRes.json<CfApiResult>();
    return c.json(
      { ok: false, error: errData.errors?.[0]?.message || "Failed to update gateway" },
      502,
    );
  }

  // 2. Handle spend limits — clear existing rules first
  const warnings: string[] = [];
  try {
    const listRes = await cfApiFetch(
      env,
      `/accounts/${env.CLOUDFLARE_ACCOUNT_ID}/ai-gateway/gateways/${env.GATEWAY_ID}/spend-limits`,
    );
    const list = await listRes.json<CfApiResult<SpendLimitRule[]>>();
    const rules = list.result ?? [];
    const deleteResults = await Promise.all(
      rules.map(async (rule) => {
        try {
          const delRes = await cfApiFetch(
            env,
            `/accounts/${env.CLOUDFLARE_ACCOUNT_ID}/ai-gateway/gateways/${env.GATEWAY_ID}/spend-limits/${rule.id}`,
            { method: "DELETE" },
          );
          if (!delRes.ok)
            return `Failed to delete spend limit rule ${rule.id} (HTTP ${delRes.status})`;
          return null;
        } catch (e: unknown) {
          return `Failed to delete spend limit rule ${rule.id}: ${errorMessage(e)}`;
        }
      }),
    );
    for (const w of deleteResults) if (w) warnings.push(w);
  } catch (e: unknown) {
    warnings.push(`Spend limit cleanup failed: ${errorMessage(e)}`);
  }

  await env.SETTINGS.put("gateway_settings", JSON.stringify(body));

  if (!body.spendLimit.enabled) {
    return c.json({
      ok: true,
      note: "Rate limiting updated. Spend limits disabled.",
      warnings,
    });
  }

  // Create a spend limit rule
  const dimensions: Record<string, { mode: "split_by_value" }> = {};
  if (body.spendLimit.scope === "model") {
    dimensions.model = { mode: "split_by_value" };
  } else if (body.spendLimit.scope === "provider") {
    dimensions.provider = { mode: "split_by_value" };
  }

  const payload = {
    budget: body.spendLimit.budget,
    window: body.spendLimit.window,
    dimensions,
  };

  try {
    const res = await cfApiFetch(
      env,
      `/accounts/${env.CLOUDFLARE_ACCOUNT_ID}/ai-gateway/gateways/${env.GATEWAY_ID}/spend-limits`,
      {
        method: "POST",
        body: JSON.stringify(payload),
      },
    );
    const data = await res.json<CfApiResult<{ id?: string }>>();
    if (!res.ok) {
      return c.json({ ok: false, error: data.errors?.[0]?.message || "API error" }, 502);
    }
    return c.json({
      ok: true,
      ruleId: data.result?.id,
      warnings,
    });
  } catch (err: unknown) {
    return c.json({ ok: false, error: errorMessage(err) }, 500);
  }
};
dualRoute("post", "/settings", settingsHandler);

// ─── API: Guardrails ──────────────────────────────────────────────────────────
// A dedicated, immediate-effect endpoint rather than folding this into
// settingsHandler's rate-limit/spend-limit batch update — flipping this one
// switch shouldn't also silently re-apply whatever rate-limit/spend-limit
// values happen to be sitting in the form.

const guardrailsHandler = async (c: AppContext) => {
  const gate = await requireAdmin(c);
  if (gate) return gate;
  const env = c.env;
  const body = (await c.req.json()) as { enabled: boolean };

  const current = await fetchCurrentGatewayConfig(env);
  const putBody = baseGatewayPutBody(current);

  // Enabling re-applies the existing hazard-category config if there is one
  // (never overwrites prior tuning), falling back to DEFAULT_GUARDRAILS on a
  // fresh enable. Disabling must *delete* the key — omitting it is how the
  // API clears Guardrails, and the spread above would otherwise carry over
  // an already-enabled config untouched.
  if (body.enabled) {
    putBody.guardrails = current.guardrails ?? DEFAULT_GUARDRAILS;
  } else {
    delete putBody.guardrails;
  }

  try {
    const res = await cfApiFetch(
      env,
      `/accounts/${env.CLOUDFLARE_ACCOUNT_ID}/ai-gateway/gateways/${env.GATEWAY_ID}`,
      { method: "PUT", body: JSON.stringify(putBody) },
    );
    if (!res.ok) {
      const errData = await res.json<CfApiResult>();
      return c.json(
        { ok: false, error: errData.errors?.[0]?.message || "Failed to update gateway" },
        502,
      );
    }
    return c.json({ ok: true, guardrailsEnabled: Boolean(putBody.guardrails) });
  } catch (err: unknown) {
    return c.json({ ok: false, error: errorMessage(err) }, 500);
  }
};
dualRoute("post", "/guardrails", guardrailsHandler);

// ─── API: Stats ──────────────────────────────────────────────────────────────

const statsHandler = async (c: AppContext) => {
  const gate = await requireAdmin(c);
  if (gate) return gate;
  const env = c.env;
  try {
    // Fetch config for live settings
    const gw = await fetchCurrentGatewayConfig(env);

    // Fetch spend-limit rules to determine live spend limit state
    let spendLimitOn = false;
    try {
      const rulesRes = await cfApiFetch(
        env,
        `/accounts/${env.CLOUDFLARE_ACCOUNT_ID}/ai-gateway/gateways/${env.GATEWAY_ID}/spend-limits`,
      );
      const rulesData = await rulesRes.json<CfApiResult<SpendLimitRule[]>>();
      spendLimitOn = Array.isArray(rulesData.result) && rulesData.result.length > 0;
    } catch {}

    // Fetch analytics via GraphQL
    const now = new Date();
    const start = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString(); // last 24h
    const graphqlRes = await cfApiFetch(env, "/graphql", {
      method: "POST",
      body: JSON.stringify({
        query: `
          query GetAIGatewayAnalytics($accountTag: String!, $gateway: String!, $start: Time!, $end: Time!) {
            viewer {
              accounts(filter: { accountTag: $accountTag }) {
                aiGatewayRequestsAdaptiveGroups(
                  limit: 1000
                  filter: { datetimeHour_geq: $start, datetimeHour_leq: $end, gateway: $gateway }
                  orderBy: [datetimeMinute_ASC]
                ) {
                  count
                  sum {
                    tokensIn
                    tokensOut
                    cost
                  }
                  dimensions {
                    model
                    provider
                    gateway
                    ts: datetimeMinute
                  }
                }
              }
            }
          }
        `,
        variables: {
          accountTag: env.CLOUDFLARE_ACCOUNT_ID,
          gateway: env.GATEWAY_ID,
          start,
          end: now.toISOString(),
        },
      }),
    });

    let requests = 0;
    let tokens = 0;
    let cost = 0;

    if (graphqlRes.ok) {
      const gqData = await graphqlRes.json<GraphQLAnalyticsResponse>();
      const groups = gqData?.data?.viewer?.accounts?.[0]?.aiGatewayRequestsAdaptiveGroups || [];
      for (const g of groups) {
        requests += g.count ?? 0;
        tokens += (g.sum?.tokensIn ?? 0) + (g.sum?.tokensOut ?? 0);
        cost += g.sum?.cost ?? 0;
      }
    }

    return c.json({
      ok: true,
      requests: requests || "-",
      tokens: tokens || "-",
      cost: cost ? `$${cost.toFixed(4)}` : "-",
      cacheTTL: gw.cache_ttl ?? 0,
      rlLimit: gw.rate_limiting_limit ?? 0,
      rlInterval: gw.rate_limiting_interval ?? 0,
      rlTechnique: gw.rate_limiting_technique ?? "fixed",
      spendLimit: spendLimitOn ? "On" : "Off",
      guardrailsEnabled: isGuardrailsOn(gw.guardrails),
      note: "Stats from Cloudflare AI Gateway Analytics.",
    });
  } catch (err: unknown) {
    return c.json({ ok: false, error: errorMessage(err) }, 500);
  }
};
dualRoute("get", "/stats", statsHandler);

// ─── Bootstrap: create gateway if missing (admin-gated) ──────────────────────

const bootstrapHandler = async (c: AppContext) => {
  const gate = await requireAdmin(c);
  if (gate) return gate;
  const env = c.env;
  try {
    const res = await cfApiFetch(
      env,
      `/accounts/${env.CLOUDFLARE_ACCOUNT_ID}/ai-gateway/gateways/${env.GATEWAY_ID}`,
    );
    if (res.status === 404) {
      const create = await cfApiFetch(env, `/accounts/${env.CLOUDFLARE_ACCOUNT_ID}/ai-gateway`, {
        method: "POST",
        body: JSON.stringify({ id: env.GATEWAY_ID, name: env.GATEWAY_ID }),
      });
      const data = await create.json<CfApiResult>();
      return c.json({
        ok: create.ok,
        created: true,
        gateway: data.result,
        error: data.errors?.[0]?.message,
      });
    }
    const data = await res.json<CfApiResult>();
    return c.json({ ok: true, created: false, gateway: data.result });
  } catch (err: unknown) {
    return c.json({ ok: false, error: errorMessage(err) }, 500);
  }
};
dualRoute("get", "/bootstrap", bootstrapHandler);

export default app;
